/** Bound credential resolution, fetch and response parsing with one deadline. */
export async function eventRequest(options, run) {
    const { signal: externalSignal, timeout, maxTotalTimeout } = options ?? {};
    externalSignal?.throwIfAborted();
    const deadlines = [timeout, maxTotalTimeout].filter((value) => value !== undefined);
    if (deadlines.some(value => !Number.isInteger(value) || value <= 0 || value > 2_147_483_647)) {
        throw new TypeError('Request timeouts must be positive 32-bit integers.');
    }
    const controller = deadlines.length ? new AbortController() : undefined;
    const signal = controller?.signal ?? externalSignal;
    const forwardAbort = () => controller?.abort(externalSignal?.reason);
    externalSignal?.addEventListener('abort', forwardAbort, { once: true });
    const timer = controller
        ? setTimeout(() => controller.abort(new DOMException('Request timed out.', 'TimeoutError')), Math.min(...deadlines))
        : undefined;
    let onAbort;
    try {
        const aborted = new Promise((_, reject) => {
            onAbort = () => reject(signal?.reason);
            signal?.addEventListener('abort', onAbort, { once: true });
        });
        return await Promise.race([run(signal), aborted]);
    }
    finally {
        if (timer !== undefined)
            clearTimeout(timer);
        externalSignal?.removeEventListener('abort', forwardAbort);
        if (onAbort)
            signal?.removeEventListener('abort', onAbort);
    }
}
